import chalk from 'chalk';
import fs from 'fs';
import path from 'path';
import { createHash } from 'crypto';
import { ensureTgcloudDir } from './state.js';
import { normalizeConfig, sameConfig } from './project-config.js';
import { toPosix } from './snapshot.js';

/**
 * Static hosting, client side. A version is a manifest `{ path: { hash, size } }`
 * of the build output plus the serving config. The local snapshot
 * (`.tgcloud/static.json`) holds hashes only: the `static` block as the server
 * last returned it.
 */

const SNAPSHOT_FILE = path.join('.tgcloud', 'static.json');

/** sha256 hex of a file's bytes. */
export function hashFile(absPath) {
  return createHash('sha256').update(fs.readFileSync(absPath)).digest('hex');
}

/**
 * Walk the build output folder. Returns null when the folder doesn't exist, else
 *   { manifest: { [posixPath]: { hash, size } }, abs: { [posixPath]: absPath },
 *     skipped: string[], nonNfc: string[] }
 * Dot-entries are skipped; paths that aren't NFC are reported in `nonNfc`.
 */
export function scanStatic(source) {
  if (!fs.existsSync(source) || !fs.statSync(source).isDirectory()) return null;
  const manifest = {};
  const abs = {};
  const skipped = [];
  const nonNfc = [];
  const walk = (rel) => {
    const dir = rel ? path.join(source, rel) : source;
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const childRel = rel ? path.join(rel, entry.name) : entry.name;
      const posix = toPosix(childRel);
      if (entry.name.startsWith('.')) { skipped.push(posix); continue; }
      const full = path.join(source, childRel);
      // Follow symlinks by what they point at; a dangling one is skipped.
      let st;
      try { st = fs.statSync(full); } catch { skipped.push(posix); continue; }
      if (st.isDirectory()) { walk(childRel); continue; }
      if (!st.isFile()) { skipped.push(posix); continue; }
      manifest[posix] = { hash: hashFile(full), size: st.size };
      abs[posix] = full;
      if (posix.normalize('NFC') !== posix) nonNfc.push(posix);
    }
  };
  walk('');
  return { manifest, abs, skipped, nonNfc };
}

/** The last `static` block the server returned, or null (none / never synced). */
export function loadStaticSnapshot() {
  if (!fs.existsSync(SNAPSHOT_FILE)) return null;
  try {
    const parsed = JSON.parse(fs.readFileSync(SNAPSHOT_FILE, 'utf-8'));
    return parsed && typeof parsed === 'object' && parsed.hash ? parsed : null;
  } catch {
    return null;
  }
}

/** Persist the `static` block verbatim; null (no static) removes the file. */
export function saveStaticSnapshot(block) {
  ensureTgcloudDir();
  if (!block) {
    fs.rmSync(SNAPSHOT_FILE, { force: true });
    return;
  }
  fs.writeFileSync(SNAPSHOT_FILE, JSON.stringify(block, null, 2) + '\n');
}

/**
 * Compare a local scan + config against the snapshot. Returns
 *   { added, modified, deleted: string[], unchanged: number,
 *     configChanged: boolean, changed: boolean }
 * With no snapshot everything local is `added` and the config counts as changed.
 */
export function staticDiff(local, config, snapshot) {
  const remote = snapshot?.manifest || {};
  const added = [];
  const modified = [];
  const deleted = [];
  let unchanged = 0;
  for (const [p, entry] of Object.entries(local.manifest)) {
    if (!(p in remote)) added.push(p);
    else if (remote[p].hash !== entry.hash) modified.push(p);
    else unchanged++;
  }
  for (const p of Object.keys(remote)) if (!(p in local.manifest)) deleted.push(p);
  const sort = (a) => a.sort((x, y) => x.localeCompare(y));
  const configChanged = !snapshot || !sameConfig(normalizeConfig(config), snapshot.config);
  const changed = added.length + modified.length + deleted.length > 0 || configChanged;
  return { added: sort(added), modified: sort(modified), deleted: sort(deleted), unchanged, configChanged, changed };
}

/** Lines telling the user the bot has a deployed Mini App this project does not manage. */
export function unmanagedStaticNotice(snapshot, configFile) {
  return [
    chalk.bold(`Static${snapshot?.url ? ` (${snapshot.url})` : ''}`),
    chalk.yellow('Warning: ') + 'the bot has a deployed Mini App that this project does not manage.',
    `Add a "static" block to ${configFile} to manage it, or set "static": false to remove it.`,
  ];
}

/** Human size: 1234567 → "1.2 MB". */
export function formatBytes(n) {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}
